def calcar_frete(peso_kg: float, regiao: str, valor_pedido: float, cupom: str | None = None, expresso: bool = False) -> float:
    # 1. Validação
    if not (peso_kg > 0 and peso_kg <= 30):
        raise ValueError("peso_kg deve ser > 0 e <= 30")
    if regiao not in ("S", "SE", "CO", "NE", "N"):
        raise ValueError("regiao inválida")
