    else:
        tarifa = 26.00 + 2.80 * math.ceil(peso_kg - 5)

    # 3. Multiplicador regional
    mult_regiao = {"S": 1.00, "SE": 1.00, "CO": 1.20, "NE": 1.35, "N": 1.50}
    tarifa *= mult_regiao[regiao]

    # 4. Expresso
    if expresso:
        tarifa *= 1.40

    # 5. Frete grátis
    if valor_pedido >= 299.90 and not expresso and regiao in ("S", "SE", "CO"):
        return 0.0

