        else:
            raise ValueError("cupom inválido")

    # 7. Frete mínimo
    if tarifa < 9.90:
        tarifa = 9.90

    # 8. Arredondamento
    return float(Decimal(str(tarifa)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

