from decimal import Decimal, ROUND_HALF_UP

def calcular_frete(peso_kg: float, regiao: str, valor_pedido: float, cupom: str | None = None, expresso: bool = False) -> float:
    # 1. Validação
    if not (peso_kg > 0 and peso_kg <= 30):
        raise ValueError("peso_kg deve ser > 0 e <= 30")
    if regiao not in ("S", "SE", "CO", "NE", "N"):
        raise ValueError("regiao deve ser uma de S, SE, CO, NE, N")
    if valor_pedido < 0:
        raise ValueError("valor_pedido deve ser >= 0")

    # 2. Tarifa base por peso
    if peso_kg <= 1.0:
        base = 12.00
    elif peso_kg <= 5.0:
        base = 12.00 + math.ceil(peso_kg - 1.0) * 3.50
    else:
        base = 26.00 + math.ceil(peso_kg - 5.0) * 2.80

    # 3. Multiplicador regional
    multipliers = {"S": 1.00, "SE": 1.00, "CO": 1.20, "NE": 1.35, "N": 1.50}
    valor_com_regiao = base * multipliers[regiao]

    # 4. Expresso
    valor_com_expresso = valor_com_regiao * 1.40 if expresso else valor_com_regiao

    # 5. Frete grátis
    if valor_pedido >= 299.90 and not expresso and regiao in ("S", "SE", "CO"):
        return 0.0

    # 6. Cupons
    if cupom is not None and cupom != "":
        cupom_lower = cupom.lower()
        if cupom_lower == "frete10":
            desconto = 0.10
        elif cupom_lower == "fretemetade":
            desconto = 0.50 if peso_kg <= 5.0 else 0.0
        else:
            raise ValueError("Cupom inválido")
    else:
        desconto = 0.0

    valor_com_desconto = valor_com_expresso * (1 - desconto)

    # 7. Frete mínimo
    if valor_com_desconto < 9.90:
        valor_com_desconto = 9.90

    # 8. Arredonde
    return float(Decimal(str(valor_com_desconto)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
